/*
# The site's faces

The type the homepage and the pages it hosts are set in, named once. A face is a
**stack** — the families in order of preference, exactly as `fontFamily` itself
takes them — so it is a theme token like any other, and a program reads one
with `Faces.helvetica`.

```declare-fragment
App [ fontFamily = { Faces.helvetica }, … ]
```

A list is a token because a token is bounded, plain data, and an ordered list of
family names is that. Writing the stack as one comma-joined string would work
too, but then the fallback order is a convention inside a string rather than
something the checker can see.

Two faces, because the homepage offers a type tuner: Helvetica is the site's,
Avenir the alternative under assessment.
*/

theme Faces [
    // The conventional Helvetica stack: the real face on Apple devices, Arial on
    // Windows; on Linux, fontconfig maps both names to its metric-compatible
    // lookalikes, and anything else falls to the system sans.

    helvetica = ["Helvetica Neue", "Helvetica", "Arial", "sans-serif"],

    // Avenir Next ships only on Apple platforms; elsewhere this falls to the
    // system face.

    avenir = ["Avenir Next", "Avenir", "system-ui", "sans-serif"]
    ]

/*
# Kit — the page's type, its figure frame, and the layer code

Every text style is a class here, so the whole piece reskins from the App's
theme record. Headings and body are the page face — Helvetica (`app.uiFace`,
which a hosting page can override); diagram labels are Avenir Next Condensed;
code, opcodes and byte counts are mono. All installed faces — the page renders
the same in the DOM, on a canvas, and in the native Mac host.

The five layer hues (`app`, `lib`, `run`, `ker`, `host`) are the one bold
system on the page: every figure speaks them, so a reader learns the code once.
*/

script { // a linear blend, the one piece of arithmetic every morph on the page uses
function mix(a, b, k) {
    return a + (b - a) * k;
}
// clamp to 0..1 — a figure's sub-phase out of one sprung scalar
function unit(v) {
    return Math.max(0, Math.min(1, v));
}
;
// gz KB per block, per build. The app/library split of the program literal
// is by class name; `boot` folds in the 0.3 KB seam module.
const SIZES = {
    calDom: { app: 11.1, lib: 7.0, core: 34.9, view: 7.8, backend: 10.5, input: 7.1, draw: 5.7,
        anim: 3.5, text: 3.4, boot: 2.5, layout: 1.8, themes: 1.7, ker: 11.5 },
    calCanvas: { app: 11.1, lib: 7.0, core: 34.9, view: 7.8, backend: 14.2, input: 9.6, draw: 8.4,
        anim: 3.5, text: 3.6, boot: 2.5, layout: 1.8, themes: 1.7, ker: 11.5 },
    calMac: { app: 11.1, lib: 7.0, core: 34.9, view: 7.8, backend: 7.0, input: 7.1, draw: 5.7,
        anim: 3.5, text: 3.4, boot: 2.5, layout: 1.8, themes: 1.7, ker: 0 }
};
const TOTALS = { calDom: 108.4, calCanvas: 117.7, calMac: 93.4 };
function sizeOf(build, key) {
    const b = SIZES[build];
    return b == null || b[key] == null ? 0 : b[key];
}
function totalOf(build) {
    return TOTALS[build] == null ? 0 : TOTALS[build];
}
// the four layer bands for a build, top to bottom — used by the layout
// (to place blocks) and by the dimension column (to label them)
const LAYER_PARTS = {
    app: ["app"], lib: ["lib"], ker: ["ker"],
    run: ["core", "view", "backend", "input", "draw", "anim", "text", "boot", "layout", "themes"]
};
function bandsOf(build, H, gap) {
    const order = ["app", "lib", "run", "ker"];
    const kb = order.map((L) => LAYER_PARTS[L].reduce((s, k) => s + sizeOf(build, k), 0));
    const all = kb.reduce((a, b) => a + b, 0);
    const usable = H - gap * 3;
    let y = 0;
    return order.map((L, i) => {
        const h = all <= 0 ? 0 : usable * kb[i] / all;
        const band = { layer: L, y: y, h: h, kb: kb[i] };
        y = y + h + gap;
        return band;
    });
}
// squarified treemap (Bruls, Huizing, van Wijk) over a rectangle —
// values in, one rect per value out, in the input order
function squarify(values, x, y, w, h) {
    const out = values.map(() => ({ x: x, y: y, w: 0, h: 0 }));
    const idx = values.map((v, i) => i).filter((i) => values[i] > 0).sort((a, b) => values[b] - values[a]);
    const total = idx.reduce((s, i) => s + values[i], 0);
    if (total <= 0 || w <= 0 || h <= 0)
        return out;
    const scale = (w * h) / total;
    let rx = x, ry = y, rw = w, rh = h;
    let row = [];
    const worst = (r, side) => {
        const areas = r.map((i) => values[i] * scale);
        const s = areas.reduce((a, b) => a + b, 0);
        const mx = Math.max(...areas), mn = Math.min(...areas);
        return Math.max((side * side * mx) / (s * s), (s * s) / (side * side * mn));
    };
    const lay = (r) => {
        const s = r.reduce((a, i) => a + values[i] * scale, 0);
        if (rw >= rh) {
            const cw = s / rh;
            let cy = ry;
            for (const i of r) {
                const ch = (values[i] * scale) / cw;
                out[i] = { x: rx, y: cy, w: cw, h: ch };
                cy += ch;
            }
            rx += cw;
            rw -= cw;
        }
        else {
            const ch = s / rw;
            let cx = rx;
            for (const i of r) {
                const cw = (values[i] * scale) / ch;
                out[i] = { x: cx, y: ry, w: cw, h: ch };
                cx += cw;
            }
            ry += ch;
            rh -= ch;
        }
    };
    for (const i of idx) {
        const side = Math.min(rw, rh);
        if (row.length == 0 || worst(row.concat([i]), side) <= worst(row, side))
            row.push(i);
        else {
            lay(row);
            row = [i];
        }
    }
    if (row.length > 0)
        lay(row);
    return out;
} /*$b*/ return { mix, unit, SIZES, TOTALS, sizeOf, totalOf, LAYER_PARTS, bandsOf, squarify }; }

class Eyebrow extends Text [ fontFamily = ["SF Mono", "ui-monospace", "Menlo", "monospace"], fontSize = 12,
    fontWeight = medium, letterSpacing = 1.4, textTransform = uppercase,
    textColor = { this.$provided("theme").muted }
    ]


class Title extends Text [ fontFamily = { this.root.uiFace },
    fontWeight = { this.root.headWeight }, letterSpacing = { this.root.headTrack * this.fontSize }, lineHeight = 1.08,
    textColor = { this.$provided("theme").ink }, wrap = true, width = 100%
    ]


class Dek extends Text [ fontSize = 20, lineHeight = 1.45, textColor = { this.$provided("theme").lead },
    wrap = true, width = 100%
    ]


// a reading paragraph: HTML flow so <b>, <i> and <code> ride inline.
// It says nothing about selection: a flowing document is selectable by its
// nature, and the page provides the value once for the Text labels around it.

class Para extends HTMLText [ width = 100%, fontSize = 17, lineHeight = 1.6,
    bodyColor = { this.$provided("theme").body }, codeColor = { this.$provided("theme").ink },
    codeBackground = { this.$provided("theme").codeBg }, linkColor = { this.$provided("theme").accent }
    ]


class Small extends Text [ fontSize = 13, lineHeight = 1.45, textColor = { this.$provided("theme").muted },
    wrap = true
    ]


// diagram label faces

class Label extends Text [ fontFamily = ["Avenir Next Condensed", "Avenir Next", "Arial Narrow", "sans-serif"],
    fontSize = 14, fontWeight = semibold, textColor = { this.$provided("theme").ink }, wrap = false
    ]


class Note extends Text [ fontFamily = ["Avenir Next Condensed", "Avenir Next", "Arial Narrow", "sans-serif"],
    fontSize = 13, fontWeight = medium, lineHeight = 1.3, textColor = { this.$provided("theme").muted }
    ]


class Mono extends Text [ fontFamily = ["SF Mono", "ui-monospace", "Menlo", "monospace"], fontSize = 12.5,
    textColor = { this.$provided("theme").ink }, wrap = false
    ]


/*
## Section head

A numbered section: the number is information (the sections follow the
program from source to pixels), then the title.
*/

class SectionHead extends View [ width = 100%,
    num: string = "",
    head: string = "",
    layout: SimpleLayout [ axis = y, spacing = 12 ],

    Eyebrow [ text = { classroot.num }, textColor = { this.$provided("theme").accent } ],
    Title [ fontSize = { this.root.width < 700 ? 30 : 38 }, text = { classroot.head } ]
    ]


/*
## Section

A numbered section of the article: its head, then whatever it holds. A use
site adds its own children after the head.
*/

class Section extends View [ width = 100%,
    num: string = "",
    head: string = "",
    layout: SimpleLayout [ axis = y, spacing = 22 ],

    SectionHead [ num = { classroot.num }, head = { classroot.head } ]
    ]


/*
## Figure

A figure breaks out of the reading column to the wide measure, with air above
and below it: a caption carrying the figure's label first, at the reading
column's measure, then the drawing — stacked and sized by `Run`, with the air
above and below as the figure's own `padding`.
*/

class Figure extends View [ width = { this.root.wide }, x = center,
    air: number = 36,
    padding = { [this.air, 0, this.air, 0] },   // air above and below, none at the sides
    layout: Run [ spacing = 16 ]
    ]


// the figure's label and its caption, together above the drawing, at the
// reading column's measure and centred over the figure

class Caption extends View [
    fig: string = "",
    text: string = "",
    measure: number = { this.root.col },
    layout: Run [ spacing = 6 ],

    Eyebrow [ wrap = true, lineHeight = 1.4, text = { classroot.fig } ],
    Text [ fontSize = 14, lineHeight = 1.5, textColor = { this.$provided("theme").muted },
        text = { classroot.text } ]
    ]


/*
## Run — the page's one hand-written layout

The INSET is the view's own `padding` now, not a layout's business: a padded
view has an inside, every child is placed from it, and the view's automatic
height counts the trailing inset back in. What is left for a layout here is the
one thing the stock stack does not do — hand each child the full inner WIDTH,
held to a child's declared `measure` (at most) or `atLeast` (at least), so a
plate's contents never size themselves.
*/

class Run extends Layout [
    spacing: number = 16,
    place() {
        // the room inside the view's padding — the CYCLE-SAFE read: 0 on a view
        // that derives its own width from these very children, which is what a
        // figure's inner stacks do
        const W = Math.max(0, this.viewExtent("width"))
        let y = 0
        return this.laid().map((c) => {
            // a child may declare a `measure` (a caption's line length: at most)
            // or an `atLeast` (a table that scrolls rather than crush: at least)
            const cap = (c).measure
            const floor = (c).atLeast
            const w0 = typeof cap == "number" && cap > 0 ? Math.min(W, cap) : W
            const w = typeof floor == "number" ? Math.max(w0, floor) : w0
            // a child held to a narrower measure is centred in the run
            const box = ({ x: Math.max(0, (W - w) / 2), y: y, w: w })
            if (c.visible) y = y + c.footprint().height + this.spacing
            return box
            })
        }
    ]


// a plate: the figure's ground

class Plate extends View [ cornerRadius = 14,
    pad: number = 22,
    gap: number = 16,
    padding = { this.pad },                     // the inset is the view's own
    layout: Run [ spacing = { classroot.gap } ],
    fill = { this.$provided("theme").panel }, stroke = { stroke(1, this.$provided("theme").line) }
    ]


// a well: a sunken plate for code and specimens

class Well extends Plate [ cornerRadius = 8, pad = 12, gap = 8, fill = { this.$provided("theme").sunk }, stroke = null ]

/*
## Layer chip — the legend's atom

A small square in a layer's hue with its name. The legend under the hero
teaches the code; every later figure just uses the colors.
*/

class Swatch extends View [ width = 12, height = 12, cornerRadius = 3 ]

class Key extends View [ height = 18,
    hue: Color = gray,
    label: string = "",
    layout: SimpleLayout [ axis = x, spacing = 7, align = center ],

    Swatch [ fill = { classroot.hue } ],
    Note [ fontSize = 13, textColor = { this.$provided("theme").lead }, text = { classroot.label } ]
    ]

/*
# Fig. 1 — what it looks like, and what it is

One sprung scalar, `k`, runs 0 → 1. At 0 the stack is the model most readers
arrive with: a file, a framework, and a browser that does the real work. At 1
it is what actually runs. Every band's y and height, and every chip's place,
is a constraint mixing the two ends by `k` — so the responsibilities physically
travel out of the browser and into the runtime. Nothing here is a transition;
it is one number moving and everything reading it.
*/

// a responsibility — sits in the browser band at k = 0, in the runtime band at k = 1

class Chip extends View [ height = 30, cornerRadius = 7,
    idx: number = 0,
    label: string = "",
    k: number = 0,
    stagger: number = { unit((this.k - this.idx * 0.035) / 0.72) },
    fill = { this.stagger > 0.5 ? this.$provided("theme").runSoft : this.$provided("theme").hostSoft },
    stroke = { stroke(1, this.stagger > 0.5 ? this.$provided("theme").run : this.$provided("theme").hostLine) },
    t: Label [ x = 10, y = center, fontSize = 13.5, fontWeight = medium, text = { classroot.label } ]
    ]


// one band of the stack: a name on the left, a note on the right, both of
// which can say two things (the assumption, the reality) crossfaded by k

class Band extends View [ cornerRadius = 9,
    hue: Color = gray,
    soft: Color = gray,
    nameA: string = "",
    nameB: string = "",
    noteA: string = "",
    noteB: string = "",
    kk: number = 0,
    fill = { this.soft },
    stroke = { stroke(1, this.hue) },
    a: Label [ x = 16, y = 12, fontSize = 16, opacity = { 1 - classroot.kk }, text = { classroot.nameA } ],
    b: Label [ x = 16, y = 12, fontSize = 16, opacity = { classroot.kk }, text = { classroot.nameB } ],
    na: Note [ y = 14, wrap = false, x = { parent.width - this.width - 16 }, opacity = { 1 - classroot.kk },
        visible = { parent.width > 520 }, text = { classroot.noteA } ],
    nb: Note [ y = 14, wrap = false, x = { parent.width - this.width - 16 }, opacity = { classroot.kk },
        visible = { parent.width > 520 }, text = { classroot.noteB } ]
    ]


class HostBox extends View [ cornerRadius = 6,
    label: string = "",
    sub: string = "",
    fill = { this.$provided("theme").panel }, stroke = { stroke(1, this.$provided("theme").hostLine) },
    col: View [ x = center, y = center,
        layout: SimpleLayout [ axis = y, spacing = 3, align = center ],
        Label [ fontSize = 14, text = { classroot.label } ],
        Note [ fontSize = 12.5, wrap = false, visible = { classroot.height > 52 && classroot.width > 150 },
            text = { classroot.sub } ]
        ]
    ]


class HeroStage extends View [ height = { this.H },
    k: number = 0,

    // one height for both states: the taller of the two, so the page below
    // never moves while the figure changes; the host band takes what is left

    runH1: number = { 136 + 40 * Math.ceil(8 / this.cols - 2) },
    H: number = { Math.max(452, 116 + this.runH1 + 70 + 90) },
    inset: number = 20,
    bw: number = { this.width - 2 * this.inset },
    cols: number = { this.width < 620 ? 2 : 4 },
    chipW: number = { (this.bw - 32 - (this.cols - 1) * 10) / this.cols },

    chipX(i: number) -> number { return this.inset + 16 + (i % this.cols) * (this.chipW + 10) },
    chipY(i: number, end: number) -> number {
        const row = Math.floor(i / this.cols)
        const top = end == 0 ? 208 : 162
        return top + row * 40
        },

    // assumed → actual geometry, one line per band

    appB: Band [ x = { classroot.inset }, width = { classroot.bw },
        y = 20, height = { mix(52, 40, classroot.k) }, kk = { classroot.k },
        hue = { this.$provided("theme").app }, soft = { this.$provided("theme").appSoft },
        nameA = "Your .declare file", nameB = "App program",
        noteA = "the part you write", noteB = "compiled: resolved, typed, dependencies extracted" ],
    lib: Band [ x = { classroot.inset }, width = { classroot.bw },
        y = { mix(84, 68, classroot.k) }, height = { mix(52, 40, classroot.k) }, kk = { classroot.k },
        hue = { classroot.k > 0.5 ? this.$provided("theme").lib : this.$provided("theme").hostLine },
        soft = { classroot.k > 0.5 ? this.$provided("theme").libSoft : this.$provided("theme").hostSoft },
        nameA = "A framework", nameB = "Library — written in Declare",
        noteA = "components, a store, re-rendering", noteB = "Button, Slider, SimpleLayout: the same kind of code as yours" ],
    run: Band [ x = { classroot.inset }, width = { classroot.bw },
        y = { mix(148, 116, classroot.k) }, height = { mix(0, classroot.runH1, classroot.k) },
        opacity = { unit(classroot.k * 3) }, kk = 1,
        hue = { this.$provided("theme").run }, soft = { this.$provided("theme").runSoft0 },
        nameA = "", nameB = "Runtime",
        noteA = "", noteB = "decides everything below: ~79 KB gz" ],
    ker: Band [ x = { classroot.inset }, width = { classroot.bw },
        y = { classroot.run.y + classroot.run.height + 8 }, height = { mix(0, 38, classroot.k) },
        opacity = { unit(classroot.k * 2 - 0.6) }, kk = 1,
        hue = { this.$provided("theme").ker }, soft = { this.$provided("theme").kerSoft },
        nameA = "", nameB = "Kernel — C, as WebAssembly or linked natively",
        noteA = "", noteB = "the settle and the geometry rules: 11.5 KB gzipped, as shipped" ],

    // the render seam — a dashed rule that exists only in the real picture

    seam: View [ x = { classroot.inset }, width = { classroot.bw }, height = 12,
        y = { classroot.ker.y + classroot.ker.height + 6 },
        opacity = { unit(classroot.k * 2 - 1) },
        draw(d: Draw) {
            d.strokeStyle = this.$provided("theme").muted
            d.lineWidth = 1
            d.setLineDash([4, 4])
            d.beginPath()
            d.moveTo(0, 6)
            d.lineTo(d.w, 6)
            d.stroke()
            },

        // the tag's width is its inset, not arithmetic over its label: a padded
        // view has an inside, and its automatic extent counts the inset back in

        tagBg: View [ x = { parent.width - this.width - 24 }, y = -2, height = 16,
            padding = [1, 8, 1, 8], fill = { this.$provided("theme").panel },
            t: Mono [ fontSize = 11, textColor = { this.$provided("theme").muted },
                text = "render seam · one interface, 58 methods" ]
            ]
        ],

    host: Band [ x = { classroot.inset }, width = { classroot.bw },
        y = { mix(148, classroot.seam.y + 18, classroot.k) },
        height = { classroot.H - 20 - this.y }, kk = { classroot.k },
        hue = { this.$provided("theme").hostLine }, soft = { this.$provided("theme").hostSoft },
        nameA = "The browser", nameB = "Host",
        noteA = "does the real work", noteB = "",

        // the three realizations, arriving only as the band settles

        boxes: View [ x = { classroot.bw < 560 ? 12 : 100 }, y = { classroot.bw < 560 ? 40 : 12 },
            width = { parent.width - this.x - 12 }, height = { Math.max(26, parent.height - this.y - 12) },
            opacity = { unit(classroot.k * 4 - 3) },
            layout: ResponsiveLayout [ plan = { [({ from: 0, flow: "row", gap: 8, share: ({ b1: 33, b2: 33, b3: 33 }) })] } ],
            b1: HostBox [ height = 100%, label = "DOM", sub = "a <div> per view, geometry as inline style" ],
            b2: HostBox [ height = 100%, label = "Canvas", sub = "one <canvas>, its own compositor" ],
            b3: HostBox [ height = 100%, label = "Mac", sub = "a CALayer tree in a 7.8 MB app" ]
            ]
        ],

    chipData: Dataset { { "rows": [
        { "i": 0, "label": "Layout" }, { "i": 1, "label": "Styling" },
        { "i": 2, "label": "Hit-testing" }, { "i": 3, "label": "Hover & press" },
        { "i": 4, "label": "Click vs. drag" }, { "i": 5, "label": "Gesture claims" },
        { "i": 6, "label": "Focus & Tab order" }, { "i": 7, "label": "Text measurement" } ] } },

    // the responsibilities, declared last so they paint over the bands

    chips: View [ width = 100%, height = 100%, datapath = { classroot.chipData.value },
        Chip [ datapath = :rows[], idx = :i, label = :label, k = { classroot.k }, width = { classroot.chipW },
            x = { classroot.chipX(this.$data(["i"])) },
            y = { mix(classroot.chipY(this.$data(["i"]), 0), classroot.chipY(this.$data(["i"]), 1), this.stagger) } ]
        ]
    ]

/*
# The compiler's trace

One line from the homepage's spring demo, as the compiler leaves it: the
source, the resolved form, the read-paths, and the kernel code — copied
verbatim from the compiled artifact, not reconstructed. It sits inline in the
reading column, as a specimen the prose points at.
*/

// one row of the trace: what it is, and the text in a well

class TraceRow extends View [
    what: string = "",
    hue: Color = gray,
    html: string = "",
    layout: ResponsiveLayout [ plan = { [({ from: 640, flow: "row", gap: 16, share: ({ tag: 20, code: 80 }) }),
        ({ from: 0, flow: "stack", gap: 8, share: ({ tag: 100, code: 100 }) })] } ],

    tag: Eyebrow [ text = { classroot.what }, textColor = { classroot.hue } ],
    code: Well [
        HTMLText [ fontSize = 13, lineHeight = 1.45,
            fontFamily = ["SF Mono", "ui-monospace", "Menlo", "monospace"],
            bodyColor = { this.$provided("theme").ink }, html = { classroot.html },
            textStyles = { { p: { textColor: this.$provided("theme").accent, fontWeight: "semibold" },
                n: { textColor: this.$provided("theme").faint } } } ]
        ]
    ]


class Trace extends Plate [ width = 100%, gap = 14,
    TraceRow [ what = "You wrote", hue = { this.$provided("theme").muted },
        html = "to = { on ? lane.width - ball.width : 0 }" ],
    TraceRow [ what = "Resolved", hue = { this.$provided("theme").muted },
        html = "to = { <span class='p'>this.root.on</span> ? <span class='p'>parent.parent.parent.lane.width</span> - <span class='p'>parent.parent.ball.width</span> : 0 }" ],
    TraceRow [ what = "Read-paths", hue = { this.$provided("theme").muted },
        html = "<span class='n'>0</span> <span class='p'>this.root.on</span><br><span class='n'>1</span> <span class='p'>parent.parent.parent.lane.width</span><br><span class='n'>2</span> <span class='p'>parent.parent.ball.width</span>" ],
    TraceRow [ what = "Kernel code", hue = { this.$provided("theme").ker },
        html = "&quot;=E<span class='p'>L0</span> <span class='p'>L1</span> <span class='p'>L2</span> - K0 ?&quot; <span class='n'>— load 0, 1, 2 · subtract · push 0 · select</span>" ]
    ]

/*
# Fig. 4 — one program, three hosts

The stack of Fig. 1 drawn to scale: each block's AREA is its share of the
gzipped production bundle. The layer bands keep Fig. 1's order (app, library,
runtime, kernel) with heights proportional to bytes; the runtime band is
subdivided into its subsystems as a squarified treemap. A switch exchanges the
backend — the one block that differs between hosts — and every other block
holds still; on the Mac the kernel also leaves the bundle, linked into the
executable as C. Beneath, the same desktop program captured on all three hosts.

The arrangement is a `TweenLayout`. The build on screen is one value on the
figure, read down the tree by everything that shows it — the blocks, the
caption, the dimension column, and the layout itself. A tween is the one
arrangement that does not re-place on its own, so the only imperative step is
the re-snapshot: the arranged view tracks the build and asks for a
`retarget(true)` once the settle has landed, and every block glides from where
it is to where the new numbers put it.

Figures: the DOM and canvas builds measured 2026-09-18 from `declarec`
production builds, gzip default level; per-subsystem bytes attributed through
source maps (two methods agree within ~1 KB per group). The Mac host loads a
platform runtime bundle rather than a per-app build, so its column reuses the
DOM build's attribution for the modules the two share and measures its own
backend the same way — minified and gzipped alone (the DOM backend so measured
lands within 0.2 KB of its attributed figure). Its kernel is native and not in
the JavaScript at all.
*/

script { }

// the arrangement: layer bands by bytes, the runtime band as a treemap

class Floorplan extends TweenLayout [
    gap: number = 3,
    place() {
        // the room this arrangement has — the arranged view's content box, not
        // its box: a strategy that reads `this.view.width` lays out at the
        // wrong number the moment anyone pads that view
        const W = this.contentExtent("width")
        const H = this.contentExtent("height")
        // which build is on screen is the arranged view's own attribute, so
        // there is one copy of it and no handler pushes it down here
        const build = (this.view).build
        const kids = this.laid()
        const keys = kids.map((c) => (c).part)
        const layerOf = kids.map((c) => (c).layer)
        const vals = keys.map((k) => sizeOf(build, k))
        const g = this.gap
        const bands = bandsOf(build, H, g)
        const boxes = kids.map(() => ({ x: 0, y: 0, w: W, h: 0, vis: true }))
        for (const b of bands) {
            const members = kids.map((c, i) => i).filter((i) => layerOf[i] == b.layer)
            if (b.layer == "run") {
                const rects = squarify(members.map((i) => vals[i]), 0, b.y, W, b.h + g)
                members.forEach((i, j) => {
                    const r = rects[j]
                    boxes[i] = { x: r.x, y: r.y, w: Math.max(0, r.w - g), h: Math.max(0, r.h - g), vis: true }
                    })
                }
            else {
                for (const i of members) boxes[i] = { x: 0, y: b.y, w: W - g, h: Math.max(1, b.h), vis: true }
                }
            }
        return boxes
        }
    ]


