                        d.setLineDash([4, 4])
                        d.lineWidth = 1
                        d.beginPath()
                        d.roundRect(0.5, 0.5, d.w - 1, d.h - 1, 8)
                        d.stroke()
                        }
                    ],

                // present but fully transparent: still on the hit path

                glass: View [ x = 300, y = 24, width = 150, height = 96, cornerRadius = 10, opacity = 0,
                    onClick() { }
                    ],
                glassMark: View [ x = 300, y = 24, width = 150, height = 96, pointerEvents = "none",
                    draw(d: Draw) {
                        d.strokeStyle = this.$provided("theme").muted
                        d.setLineDash([5, 4])
                        d.lineWidth = 1.2
                        d.beginPath()
                        d.roundRect(0.5, 0.5, d.w - 1, d.h - 1, 10)
                        d.stroke()
                        },
                    Note [ x = 12, y = 12, width = 126, fontSize = 12.5, pointerEvents = "none",
                        text = { classroot.row.scene.world.glass.hovered ? "Hit: opacity 0, still present" : "Invisible glass (opacity 0)" },
                        textColor = { classroot.row.scene.world.glass.hovered ? this.$provided("theme").ink : this.$provided("theme").muted } ]
                    ],

                // seen, never touched

                badge: View [ x = 290, y = 214, width = 140, height = 34, cornerRadius = 17, pointerEvents = "none",
                    fill = { this.$provided("theme").panel }, stroke = { stroke(1, this.$provided("theme").hostLine) },
                    Note [ x = center, y = center, fontSize = 12, pointerEvents = "none", text = "a label: clicks pass through" ]
                    ]
